$main=$bath.plans.main;$m02=@($main|Where-Object id -eq 'M-02')[0];$m01=@($main|Where-Object id -eq 'M-01')[0];$m03=@($main|Where-Object id -eq 'M-03')[0];$m04=@($main|Where-Object id -eq 'M-04')[0];$m05=@($main|Where-Object id -eq 'M-05')[0];$ox=[double]$m02.x;$oy=[double]$m02.y
$blocks=@{};foreach($b in @($m01,$m02,$m03,$m04,$m05)){$blocks[$b.id]=[ordered]@{id=$b.id;x=([double]$b.x-$ox);y=([double]$b.y-$oy);w=[double]$b.w;d=[double]$b.d}}
