function PointSeg181($p,$a,$b){$vx=$b.x-$a.x;$vy=$b.y-$a.y;$len=$vx*$vx+$vy*$vy;if($len-lt1e-12){return [Math]::Sqrt(($p.x-$a.x)*($p.x-$a.x)+($p.y-$a.y)*($p.y-$a.y))};$t=(($p.x-$a.x)*$vx+($p.y-$a.y)*$vy)/$len;$t=[Math]::Max(0.0,[Math]::Min(1.0,[double]$t));$qx=$a.x+$t*$vx;$qy=$a.y+$t*$vy;return [Math]::Sqrt(($p.x-$qx)*($p.x-$qx)+($p.y-$qy)*($p.y-$qy))}
function Orient181($a,$b,$c){return (($b.x-$a.x)*($c.y-$a.y)-($b.y-$a.y)*($c.x-$a.x))}
function OnSeg181($a,$b,$p){return ($p.x-ge([Math]::Min($a.x,$b.x)-1e-9)-and$p.x-le([Math]::Max($a.x,$b.x)+1e-9)-and$p.y-ge([Math]::Min($a.y,$b.y)-1e-9)-and$p.y-le([Math]::Max($a.y,$b.y)+1e-9))}
function SegDist181($a,$b,$c,$d){
  $o1=Orient181 $a $b $c; $o2=Orient181 $a $b $d; $o3=Orient181 $c $d $a; $o4=Orient181 $c $d $b
  $proper=((($o1 -gt 0 -and $o2 -lt 0) -or ($o1 -lt 0 -and $o2 -gt 0)) -and (($o3 -gt 0 -and $o4 -lt 0) -or ($o3 -lt 0 -and $o4 -gt 0)))
  $touch=(($o1 -eq 0 -and (OnSeg181 $a $b $c)) -or ($o2 -eq 0 -and (OnSeg181 $a $b $d)) -or ($o3 -eq 0 -and (OnSeg181 $c $d $a)) -or ($o4 -eq 0 -and (OnSeg181 $c $d $b)))
  if($proper -or $touch){return 0.0}
  $ds=@((PointSeg181 $a $c $d),(PointSeg181 $b $c $d),(PointSeg181 $c $a $b),(PointSeg181 $d $a $b)); return [double](($ds|Measure-Object -Minimum).Minimum)
}
function SegRect181($a,$b,$r){$l=[double]$r.x;$t=[double]$r.y;$rr=$l+[double]$r.w;$bb=$t+[double]$r.d;if(($a.x-ge$l-and$a.x-le$rr-and$a.y-ge$t-and$a.y-le$bb)-or($b.x-ge$l-and$b.x-le$rr-and$b.y-ge$t-and$b.y-le$bb)){return 0.0};$c=@([pscustomobject]@{x=$l;y=$t},[pscustomobject]@{x=$rr;y=$t},[pscustomobject]@{x=$rr;y=$bb},[pscustomobject]@{x=$l;y=$bb});$ds=New-Object System.Collections.Generic.List[double];for($i=0;$i-lt4;$i++){$ds.Add((SegDist181 $a $b $c[$i] $c[($i+1)%4]))};return [double](($ds|Measure-Object -Minimum).Minimum)}
function RouteClearances181($path,$targets){$result=New-Object System.Collections.Generic.List[object];for($i=0;$i-lt$path.Count-1;$i++){foreach($t in $targets){$d=SegRect181 $path[$i] $path[$i+1] $t;$result.Add([pscustomobject]@{segment=$i;target=$t.id;centerline_distance_ft=[Math]::Round($d,6);buffer_clearance_in=[Math]::Round(($d-1.5)*12,4)})}};return $result.ToArray()}
function Summarize181($values){$summary=New-Object System.Collections.Generic.List[object];foreach($g in ($values|Group-Object target)){$summary.Add(@($g.Group|Sort-Object buffer_clearance_in|Select-Object -First 1)[0])};return $summary.ToArray()}
$oldClear=RouteClearances181 $original $obstacles;$newClearAll=RouteClearances181 $route $obstacles;$newClear=@($newClearAll|Where-Object target -ne 'west_of_core');$oldSummary=Summarize181 $oldClear;$newSummaryAll=Summarize181 $newClearAll;$newSummary=@($newSummaryAll|Where-Object target -ne 'west_of_core');$oldWorst=@($oldSummary|Sort-Object buffer_clearance_in|Select-Object -First 1)[0];$newWorst=@($newSummary|Sort-Object buffer_clearance_in|Select-Object -First 1)[0];$westWorst=@($newSummaryAll|Where-Object target -eq 'west_of_core')[0];$tableWorst=@($newSummary|Where-Object target -eq 'dining-table')[0];$stoolWorst=@($newSummary|Where-Object target -eq 'assumed-stools')[0]
